declare(strict_types=1);
return [
"CREATE TABLE hosting_pools (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,name VARCHAR(120) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB",
"CREATE TABLE hosting_servers (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,pool_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,environment VARCHAR(16) CHARACTER SET ascii NOT NULL DEFAULT 'mock',credential_encrypted LONGTEXT NOT NULL,capacity INT UNSIGNED NOT NULL,weight SMALLINT UNSIGNED NOT NULL,healthy BOOLEAN NOT NULL,observed_at DATETIME(6) NOT NULL,fresh_seconds INT UNSIGNED NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,capabilities LONGTEXT NOT NULL CHECK(JSON_VALID(capabilities)),CHECK(environment='mock'),CHECK(capacity>0 AND weight>0 AND fresh_seconds BETWEEN 1 AND 3600),KEY ix_host_pool(pool_id,enabled,healthy,id),FOREIGN KEY(pool_id) REFERENCES hosting_pools(id)) ENGINE=InnoDB",
"CREATE TABLE hosting_mappings (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,product_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,pool_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,package_name VARCHAR(64) CHARACTER SET ascii NOT NULL,reseller_scope VARCHAR(64) CHARACTER SET ascii NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE KEY uq_host_mapping(product_id,pool_id),FOREIGN KEY(pool_id) REFERENCES hosting_pools(id)) ENGINE=InnoDB",
"CREATE TABLE hosting_reservations (operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,server_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,mapping_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,package_name VARCHAR(64) CHARACTER SET ascii NOT NULL,reseller_scope VARCHAR(64) CHARACTER SET ascii NOT NULL,status VARCHAR(16) CHARACTER SET ascii NOT NULL DEFAULT 'HELD',created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_host_capacity(server_id,status),FOREIGN KEY(server_id) REFERENCES hosting_servers(id),FOREIGN KEY(mapping_id) REFERENCES hosting_mappings(id),CHECK(status IN ('HELD','RELEASED'))) ENGINE=InnoDB",
"CREATE TABLE mock_hosting_accounts (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,server_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,create_operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,package_name VARCHAR(64) CHARACTER SET ascii NOT NULL,status VARCHAR(16) CHARACTER SET ascii NOT NULL,starts_at DATETIME(6) NOT NULL,ends_at DATETIME(6) NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,UNIQUE KEY uq_mock_host_service(server_id,service_id),CHECK(status IN ('ACTIVE','SUSPENDED','TERMINATED'))) ENGINE=InnoDB",
"CREATE TABLE mock_hosting_calls (operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,server_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,action VARCHAR(32) CHARACTER SET ascii NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii NOT NULL,status VARCHAR(24) CHARACTER SET ascii NOT NULL,resource_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,safe_code VARCHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6)) ENGINE=InnoDB",
"CREATE TRIGGER mock_host_call_update BEFORE UPDATE ON mock_hosting_calls FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable mock call'",
"CREATE TRIGGER mock_host_call_delete BEFORE DELETE ON mock_hosting_calls FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable mock call'",
"CREATE TRIGGER svc_provider_request_binding BEFORE UPDATE ON svc_provider_operations FOR EACH ROW BEGIN IF OLD.lifecycle_operation_id<>NEW.lifecycle_operation_id OR OLD.provider<>NEW.provider OR OLD.request_encrypted<>NEW.request_encrypted OR OLD.request_fingerprint<>NEW.request_fingerprint OR (OLD.server_id IS NOT NULL AND NOT(OLD.server_id <=> NEW.server_id)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable provider request'; END IF; END",
];
